window.kbPageData["views/entry/k-3d4f3c0b9cdabc1e"] = {"key":"entry/k-3d4f3c0b9cdabc1e","state":{"route":"entry/k-3d4f3c0b9cdabc1e"},"node":{"id":"k-3d4f3c0b9cdabc1e","mode":"k","title":"城镇开发边界外的用地管控","type":"制度与规则","domain":"公共管理","reading":"","intro":"","priority":100,"aliases":["城镇开发边界外的用途限制及零星用地条件"],"qs":["江苏 2024 C类 行测#15"],"current":false,"candidates":true,"sources":[],"basisGroup":"","authority":null,"sourceOnly":false,"reviewSet":"单次条目","independentCount":1,"repeatPositions":0,"directorySummary":"城镇开发边界外不得进行城镇集中建设，不得规划建设各类开发区和产业园区，也不得规划城镇居住用地。落实耕地保护、节约用地和生态环境保护制度后，可因合理需要规划布局有特定选址要求的零星城镇建设用地，并按国土空间规划及用途管制要求实施监督。","review":{"definition":"城镇开发边界外不得进行城镇集中建设，不得规划建设各类开发区和产业园区，也不得规划城镇居住用地。落实耕地保护、节约用地和生态环境保护制度后，可因合理需要规划布局有特定选址要求的零星城镇建设用地，并按国土空间规划及用途管制要求实施监督。","explanation":"第15题B项的数字产业园属于边界外禁止规划建设的产业园区。C项只说为扩大城镇用地而缩减风景名胜区范围，所述条件不足以说明符合相关保护和规划要求。材料允许的情形是符合条件、具有特定选址要求的零星用地。","references":[],"evidence":"可规划布局有特定\n选址要求的零星城镇建设用地","disposition":"独立词条","basis":"据原题和解析编释。"}},"questions":{"江苏 2024 C类 行测#15":{"paper":"江苏 2024 C类 行测","n":15,"mod":"常识判断","src":["3f1ec77ae8a18519b57e.pdf",3],"asrc":["02d6b49839583bdaf297.pdf",5],"card":"e7c7edb183fdc6becf63ce25","links":[{"id":"k-3d4f3c0b9cdabc1e","role":"直接考查","why":"边界外禁止城镇集中建设及规划建设各类开发区和产业园区，符合保护和规划要求的特定选址项目可安排零星建设用地。"}]}},"terms":{},"references":{},"topics":[],"units":{"k-3d4f3c0b9cdabc1e":[["江苏 2024 C类 行测#15"]]}};
